rules.logic:
if (!element || !element.querySelector) return;

var categoryEl = element.querySelector('.text-link, .text-magenta-9, .text-rose-9');
if (!categoryEl) return;

var text = (categoryEl.textContent || '').trim().toLowerCase();
var lifestyleCategories = ['relationships', 'fashion', 'music', 'lifestyle', 'style', 'food', 'health'];

var isLifestyle = false;
for (var i = 0; i < lifestyleCategories.length; i++) {
    if (text === lifestyleCategories[i]) {
        isLifestyle = true;
        break;
    }
}

if (isLifestyle) {
    element.style.display = 'none';
} else {
    element.style.display = '';
}
